// Runs the code builder tests and writes the C++ code generated by them to the given files.
// The test results are ignored because the generated code isn't available yet.
// Tests run in a child process which is restarted if a test crashes (code after a failed
// assertion can crash), so that the code of all remaining tests is collected.

#include <gtest/gtest.h>
#include <gmock/gmock.h>
#include <engine/internal/codegen/cpp/cppcompilercontext.h>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <map>
#include <set>
#include <vector>

using namespace libscratchcpp;

namespace
{

class ProgressListener : public testing::EmptyTestEventListener
{
    public:
        ProgressListener(const std::filesystem::path &file) :
            m_file(file, std::ios::app)
        {
        }

        void OnTestStart(const testing::TestInfo &info) override { write("S", info); }
        void OnTestEnd(const testing::TestInfo &info) override { write("E", info); }

    private:
        void write(const std::string &prefix, const testing::TestInfo &info) { m_file << prefix << " " << info.test_suite_name() << "." << info.name() << std::endl; }

        std::ofstream m_file;
};

int runChild(const std::filesystem::path &dir)
{
    std::ifstream excluded(dir / "excluded.txt");
    std::string line, filter = "-";

    while (std::getline(excluded, line)) {
        if (!line.empty())
            filter += line + ":";
    }

    if (filter.size() > 1)
        GTEST_FLAG_SET(filter, filter);

    GMOCK_FLAG_SET(verbose, "error");

    std::ofstream sources(dir / "sources.txt", std::ios::app | std::ios::binary);

    CppCompilerContext::setSourceCallback([&sources](uint64_t hash, const std::string &source) {
        sources << hash << " " << source.size() << "\n" << source;
        sources.flush();
    });

    testing::TestEventListeners &listeners = testing::UnitTest::GetInstance()->listeners();
    delete listeners.Release(listeners.default_result_printer());
    listeners.Append(new ProgressListener(dir / "progress.txt"));
    (void)RUN_ALL_TESTS();

    std::ofstream(dir / "progress.txt", std::ios::app) << "DONE" << std::endl;

    // Skip static destructors (failed tests can leave mocks in a bad state)
    std::_Exit(0);
}

} // namespace

int main(int argc, char **argv)
{
    testing::InitGoogleTest(&argc, argv);

    if (argc == 3 && std::string(argv[1]) == "--child")
        return runChild(argv[2]);

    if (argc < 2) {
        std::cerr << "usage: " << argv[0] << " <output files...>" << std::endl;
        return 1;
    }

    const std::filesystem::path dir = std::filesystem::path(argv[1]).parent_path() / "codegen_test_generator_work";
    std::filesystem::remove_all(dir);
    std::filesystem::create_directories(dir);

    std::set<std::string> excluded;
    bool done = false;

    while (!done) {
        const std::string cmd = "\"" + std::string(argv[0]) + "\" --child \"" + dir.string() + "\"";
        (void)std::system(cmd.c_str());

        std::ifstream progress(dir / "progress.txt");
        std::set<std::string> started, crashed;
        std::string line;

        while (std::getline(progress, line)) {
            if (line == "DONE")
                done = true;
            else if (line.rfind("S ", 0) == 0)
                started.insert(line.substr(2));
            else if (line.rfind("E ", 0) == 0) {
                started.erase(line.substr(2));
                excluded.insert(line.substr(2));
            }
        }

        if (done)
            break;

        size_t oldCount = excluded.size();
        excluded.insert(started.begin(), started.end());

        if (excluded.size() == oldCount) {
            std::cerr << "error: the test process failed outside of a test" << std::endl;
            return 1;
        }

        std::ofstream excludedFile(dir / "excluded.txt");

        for (const std::string &test : excluded)
            excludedFile << test << "\n";
    }

    std::map<uint64_t, std::string> sources;
    std::ifstream sourcesFile(dir / "sources.txt", std::ios::binary);
    uint64_t hash;
    size_t size;

    while (sourcesFile >> hash >> size) {
        sourcesFile.get();
        std::string source(size, '\0');
        sourcesFile.read(source.data(), size);
        sources[hash] = source;
    }

    // The code is split into multiple files to reduce compile time and memory usage
    const size_t fileCount = argc - 1;
    std::vector<std::ofstream> files;

    for (size_t i = 0; i < fileCount; i++) {
        files.emplace_back(argv[i + 1]);

        if (!files.back().is_open()) {
            std::cerr << "error: could not open " << argv[i + 1] << std::endl;
            return 1;
        }

        files.back() << CppCompilerContext::sourceHeader();
    }

    size_t i = 0;

    for (const auto &[hash, source] : sources)
        files[i++ % fileCount] << source << "\n";

    files.clear();
    std::cout << "Generated " << sources.size() << " code units" << std::endl;
    std::_Exit(0);
}
